<?php require_once '../../includes/auth.php';require_once '../../config/conexion.php';exigir_roles(['Administrador del sistema','Visualización y actualización']);$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT n.nombre_neonato,n.exp_neonato,e.id_espacio,e.numero_espacio FROM pacientes_neonatos n JOIN espacios_neonatales e ON e.id_neonato=n.id_neonato WHERE n.id_neonato=?');$q->execute([$id]);$n=$q->fetch();if(!$n)exit('No se encontró el ingreso activo.');$titulo='Confirmar egreso';require '../../includes/header.php';?><h1>Confirmar alta / egreso</h1><div class="panel"><p>¿Confirmas el egreso de <b><?= h($n['nombre_neonato']) ?></b> (<?= h($n['exp_neonato']) ?>) del espacio <b><?= h($n['numero_espacio']) ?></b>?</p><form method="post" action="confirmar_egreso.php"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id_neonato" value="<?= $id ?>"><button class="boton alerta-btn">Confirmar egreso y liberar espacio</button> <a class="boton" href="index.php">Cancelar</a></form></div><?php require '../../includes/footer.php';?>
